def read_port(config):
    try:
        raw = config['port']
    except KeyError:
        return 8080
    try:
        return int(raw)
    except ValueError:
        raise ValueError(f'port must be a whole number, got {raw!r}')

assert read_port({'port': '5432'}) == 5432
assert read_port({}) == 8080
try:
    read_port({'port': 'http'})
    raise AssertionError('expected ValueError')
except ValueError as err:
    assert 'http' in str(err)
print('ok')
